-- Follow-up to the immutable 22-event publication: learner-facing citations only.

-- Owner-delegated content review, project ueolfjujjybutyuyfxha, 2026-10-26.

-- Single-use guard; no event, source identity, historical claim, policy or schema change.

begin isolation level serializable;

set local lock_timeout='5s';

create temporary table reviewed_citations(id uuid primary key,before_row jsonb not null,citation text not null) on commit drop;


do $preflight$ begin

if (select count(*) from reviewed_citations) <> 24 then raise exception 'Expected 24 reviewed sources'; end if;

perform 1 from public.sources s join reviewed_citations r using(id) order by s.id for update of s;

if exists(select 1 from reviewed_citations r left join public.sources s using(id) where s.id is null or (to_jsonb(s)-'created_by'-'updated_by') is distinct from r.before_row) then raise exception 'Reviewed source changed; take a fresh snapshot'; end if;

if exists(select 1 from public.event_sources l join reviewed_citations r on r.id=l.source_id join public.historical_events e on e.id=l.event_id where e.slug not in ('viet-nam-gia-nhap-wto-2007','viet-nam-gia-nhap-asean-1995','binh-thuong-hoa-quan-he-viet-my-1995','bao-ve-chu-quyen-gac-ma-1988','chien-dich-viet-bac-1947','chien-dich-bien-gioi-1950','phong-trao-dong-khoi-1960','hue-gianh-chinh-quyen-1945','sai-gon-gianh-chinh-quyen-1945','chien-thang-buon-ma-thuot-1975','giai-phong-hue-1975','giai-phong-da-nang-1975','phong-trao-dong-du','nguyen-ai-quoc-dai-hoi-tours-1920','thanh-lap-dang-cong-san-viet-nam-1930','thanh-lap-viet-minh-1941','chien-thang-ap-bac-1963','chien-thang-van-tuong-1965','tien-cong-chien-luoc-1972','nghi-quyet-khoan-10-1988','dai-hoi-dang-lan-thu-viii-1996','cptpp-co-hieu-luc-voi-viet-nam-2019')) then raise exception 'Source has an event outside the approved allowlist'; end if;

end $preflight$;

update public.sources s set citation=r.citation,accessed_at='2026-10-26'::date from reviewed_citations r where s.id=r.id;

select jsonb_build_object('updated_sources',(select count(*) from public.sources s join reviewed_citations r using(id) where s.citation=r.citation and s.accessed_at='2026-10-26'::date),'event_counts',(select jsonb_object_agg(workflow_status,cnt) from(select workflow_status,count(*) cnt from public.historical_events group by workflow_status)c)) as citations;

commit;
